// Seul endroit qui lit la réponse Brain (brain.keyword, response_format "concise", AGENT-1049) :
// URI du passage, match_type ("exact_identifier" quand la requête est un identifiant) et score.
// Une réponse en forme détaillée (document.file_path, image Brain antérieure à la forme concise)
// échoue explicitement : aucun repli silencieux, aucun résultat vide déguisé.
const URI_PATTERN = /^company-memory:\/\/revisions\/([a-z0-9][a-z0-9_-]{0,63})$/;
const isObject = (hit) => !!hit && typeof hit === "object";
const brainUri = (hit) => (isObject(hit) && typeof hit.uri === "string" ? hit.uri : null);
let hits = search.results;
if (hits === null && search.total_results === 0) hits = [];
if (!Array.isArray(hits)) throw new Error("invalid_brain_response");
if (hits.some(hit => isObject(hit) && brainUri(hit) === null && hit.document)) throw new Error("brain_concise_unsupported");
if (hits.length > 0 && hits.every(hit => brainUri(hit) === null)) throw new Error("invalid_brain_response");
const byId = new Map();
for (const hit of hits) {
  const uri = brainUri(hit);
  const m = uri === null ? null : URI_PATTERN.exec(uri);
  if (!m) continue;
  const entry = byId.get(m[1]) || {proposal_id: m[1], match_type: "other", score: 0};
  if (hit.match_type === "exact_identifier") entry.match_type = "exact_identifier";
  if (typeof hit.score === "number" && hit.score > entry.score) entry.score = hit.score;
  byId.set(m[1], entry);
}
return [...byId.values()].slice(0, 10);

// Une seule requête Memory pour tous les candidats : les révisions validées dont l'identifiant est un candidat
// (texte, citations, échéance, titre, dates) et celles dont previous_revision est un candidat (successeurs).
// Les identifiants sont inlinés entre quotes : chacun est revérifié contre le slug, rien d'autre n'entre dans le SQL.
const SLUG = /^[a-z0-9][a-z0-9_-]{0,63}$/;
if (candidates !== null && !Array.isArray(candidates)) throw new Error("invalid_candidates");
const ids = (candidates || []).map(c => (c && typeof c === "object" ? c.proposal_id : c));
if (ids.length > 10) throw new Error("too_many_candidates");
for (const id of ids) if (typeof id !== "string" || !SLUG.test(id)) throw new Error("invalid_candidate_id");
// Sans candidat : le moteur n'a pas d'étape conditionnelle (une decision passerait par un Workflow enfant), la
// requête est donc une requête qui ne renvoie rien, sans clause previous_revision. Toutes les révisions sans
// prédécesseur ont previous_revision = "" : une liste contenant '' les renverrait toutes (cap maxRows, truncated).
if (ids.length === 0) {
  return {ids, sql: "SELECT external_id, name, status, attributes FROM v_entities"
    + " WHERE entity_type = 'company_memory_revision' AND external_id IN ('')"};
}
// Garde-fou : la liste des clauses IN ne contient jamais la chaîne vide (les slugs font au moins un caractère).
if (ids.some(id => id.length === 0)) throw new Error("empty_candidate_id");
const list = ids.map(id => "'" + id + "'").join(", ");
const sql = "SELECT external_id, name, status, attributes FROM v_entities"
  + " WHERE entity_type = 'company_memory_revision' AND status = 'validated'"
  + " AND (external_id IN (" + list + ") OR json_extract_string(attributes, '$.previous_revision') IN (" + list + "))";
return {ids, sql};

// Revalidation sans sous-Workflow : une requête Memory (révisions validées des candidats et de leurs successeurs)
// et un listage de /company-memory (marqueurs natifs superseded-ID.json). Un candidat sans ligne Memory validée
// est exclu ; un candidat remplacé (successeur validé dans Memory ou marqueur natif) est exclu ; une échéance
// dépassée ou illisible est exclue, comme dans memory-query. Les exclus sont comptés dans suppressed_count.
const SLUG = /^[a-z0-9][a-z0-9_-]{0,63}$/;
if (candidates !== null && !Array.isArray(candidates)) throw new Error("invalid_candidates");
// Sans candidat Brain : réponse vide, quelle que soit la réponse Memory (requête vide de build-revision-query).
if (!candidates || candidates.length === 0) {
  return {results: [], summary: "Aucune révision validée trouvée.", candidate_count: 0, suppressed_count: 0,
    excerpt_budget_chars: 10 * 2 * (400 + 2 * 4)};
}
// Memory répond rows=null quand aucune ligne ne correspond : résultat vide. Toute autre forme est une panne.
if (!memory_rows || typeof memory_rows !== "object") throw new Error("memory_lookup_unavailable");
const rows = Array.isArray(memory_rows.rows) ? memory_rows.rows : (memory_rows.rows === null ? [] : null);
if (rows === null) throw new Error("memory_lookup_unavailable");
if (memory_rows.truncated === true) throw new Error("memory_rows_truncated");
if (!Array.isArray(files)) throw new Error("storage_listing_unavailable");
// attributes arrive en objet ou en chaîne JSON selon le moteur de Memory : les deux sont acceptés.
const attributesOf = (value) => {
  let v = value;
  for (let i = 0; i < 2 && typeof v === "string"; i++) {
    if (!v.trim()) return {};
    try { v = JSON.parse(v); } catch (e) { throw new Error("memory_attributes_invalid"); }
  }
  if (v === null || v === undefined) return {};
  if (typeof v !== "object" || Array.isArray(v)) throw new Error("memory_attributes_invalid");
  return v;
};
const text = (v) => (typeof v === "string" ? v : "");
const stored = new Map();
const successorsOf = new Map();
for (const row of rows) {
  // Lignes positionnelles : external_id, name, status, attributes (ordre du SELECT).
  const cells = Array.isArray(row) ? row
    : (row && typeof row === "object" ? [row.external_id, row.name, row.status, row.attributes] : null);
  if (!cells || typeof cells[0] !== "string" || !SLUG.test(cells[0])) throw new Error("memory_row_invalid");
  if (cells[2] !== "validated") continue;
  const attrs = attributesOf(cells[3]);
  stored.set(cells[0], {name: cells[1], attrs});
  const previous = text(attrs.previous_revision);
  if (previous && previous !== cells[0]) {
    if (!successorsOf.has(previous)) successorsOf.set(previous, new Set());
    successorsOf.get(previous).add(cells[0]);
  }
}
const paths = new Set(files.map(f => (f && typeof f.path === "string" ? f.path : "")));
// Référence de source : attribut source_ref, sinon première citation. citations arrive en tableau, en chaîne JSON
// de tableau, ou en chaîne rendue à la Go « [ref] » (révisions indexées avant le rendu json) : une seule citation,
// l'intérieur des crochets tel quel (une référence peut contenir des espaces, elle n'est jamais découpée).
const firstCitation = (value) => {
  if (Array.isArray(value)) return value.find(x => typeof x === "string" && x.trim()) || "";
  if (typeof value !== "string") return "";
  const s = value.trim();
  if (!(s.startsWith("[") && s.endsWith("]"))) return s;
  try {
    const parsed = JSON.parse(s);
    if (Array.isArray(parsed)) return parsed.find(x => typeof x === "string" && x.trim()) || "";
  } catch (e) { /* forme Go : pas du JSON */ }
  return s.slice(1, -1).trim();
};
// Titre des révisions indexées avant l'attribut title : fragment de la référence entre « # » et le dernier « @ »,
// sinon l'identifiant.
const derivedTitle = (ref, id) => {
  const hash = ref.indexOf("#");
  if (hash < 0) return id;
  const fragment = ref.slice(hash + 1);
  const at = fragment.lastIndexOf("@");
  return (at < 0 ? fragment : fragment.slice(0, at)).trim() || id;
};
const now = Date.now();
const all = (candidates || []).map(c => {
  const id = c && typeof c === "object" ? c.proposal_id : c;
  if (typeof id !== "string" || !SLUG.test(id)) throw new Error("invalid_candidate_id");
  const base = {proposal_id: id, match_type: c.match_type === "exact_identifier" ? "exact_identifier" : "other",
    score: typeof c.score === "number" ? c.score : 0};
  const entry = stored.get(id);
  if (!entry) return {...base, status: "not_indexed"};
  const successors = [...(successorsOf.get(id) || [])].sort();
  if (successors.length || paths.has("/company-memory/superseded-" + id + ".json")) {
    return {...base, status: "superseded", superseded_by: successors.length === 1 ? successors[0] : ""};
  }
  const a = entry.attrs;
  const expires_at = text(a.expires_at);
  const due = Date.parse(expires_at);
  if (Number.isNaN(due) || due <= now) return {...base, status: "expired"};
  const source_ref = text(a.source_ref).trim() || firstCitation(a.citations);
  return {...base, status: "validated", answer: text(entry.name), citations: source_ref ? [source_ref] : [], expires_at,
    title: text(a.title) || derivedTitle(source_ref, id),
    source_date: text(a.source_date), reviewed_at: text(a.reviewed_at), superseded_by: ""};
});
// Extraits : jusqu'à deux fenêtres de WINDOW caractères, choisies par couverture des termes de la requête
// (mots de plus de deux lettres, accents et casse ignorés), non chevauchantes, dans l'ordre du texte.
// Repli : le début du texte. Borne par réponse : 10 résultats x 2 fenêtres x (WINDOW + 2 x CUT).
const WINDOW = 400, CUT = 4, MAX_WINDOWS = 2;
const BUDGET = 10 * MAX_WINDOWS * (WINDOW + 2 * CUT);
const norm = (text) => String(text).normalize("NFD").replace(/\p{M}/gu, "").toLowerCase();
const queryTerms = new Set((norm(query).match(/[\p{L}\p{N}]+/gu) || []).filter(t => [...t].length > 2));
const occurrences = (flat) => {
  const found = [];
  for (const m of flat.matchAll(/[\p{L}\p{N}]+/gu)) {
    const t = norm(m[0]);
    if (queryTerms.has(t)) found.push({pos: m.index, term: t});
  }
  return found;
};
const windowsOf = (flat) => {
  const occ = occurrences(flat);
  if (occ.length === 0) return [{start: 0, end: Math.min(WINDOW, flat.length)}];
  const starts = [...new Set([0, ...occ.map(o => Math.max(0, o.pos - 60))])].sort((a, b) => a - b);
  const covered = (s) => new Set(occ.filter(o => o.pos >= s && o.pos < s + WINDOW).map(o => o.term));
  let first = null;
  for (const s of starts) {
    const c = covered(s);
    if (c.size && (!first || c.size > first.cov.size)) first = {s, cov: c};
  }
  const picks = [first];
  let second = null;
  for (const s of starts) {
    if (s < first.s + WINDOW && s + WINDOW > first.s) continue;
    const gain = [...covered(s)].filter(t => !first.cov.has(t)).length;
    if (gain > 0 && (!second || gain > second.gain)) second = {s, gain};
  }
  if (second && MAX_WINDOWS > 1) picks.push(second);
  return picks.sort((a, b) => a.s - b.s).map(p => ({start: p.s, end: Math.min(flat.length, p.s + WINDOW)}));
};
const clean = (value) => String(value === undefined || value === null ? "" : value).replace(/\s+/g, " ").trim();
const cut = (value, max) => [...clean(value)].slice(0, max).join("");
const excerptsOf = (text) => {
  const flat = String(text || "").replace(/\s+/g, " ").trim();
  if (!flat) return [];
  return windowsOf(flat).map(w => (w.start > 0 ? "[…] " : "") + flat.slice(w.start, w.end) + (w.end < flat.length ? " […]" : ""));
};
const timeOf = (x) => {
  const t = Date.parse(x.source_date || x.reviewed_at || "");
  return Number.isNaN(t) ? 0 : t;
};
const valid = all.filter(x => x.status === "validated");
// Identifiants exacts d'abord, par date décroissante (une correction récente précède la section corrigée) ;
// ensuite les autres, par score décroissant.
const exact = valid.filter(x => x.match_type === "exact_identifier")
  .sort((a, b) => timeOf(b) - timeOf(a) || a.proposal_id.localeCompare(b.proposal_id));
const others = valid.filter(x => x.match_type !== "exact_identifier")
  .sort((a, b) => (b.score || 0) - (a.score || 0) || a.proposal_id.localeCompare(b.proposal_id));
const results = [...exact, ...others].map(x => {
  const sourced = x.source_date ? {date: x.source_date, date_kind: "source"}
    : (x.reviewed_at ? {date: x.reviewed_at, date_kind: "revue"} : {date: "", date_kind: "inconnue"});
  return {
    proposal_id: x.proposal_id,
    title: cut(x.title, 200),
    date: clean(sourced.date),
    date_kind: sourced.date_kind,
    source_ref: cut((x.citations && x.citations[0]) || "", 300),
    match_type: x.match_type === "exact_identifier" ? "exact_identifier" : "other",
    review_due: clean(x.expires_at),
    ...(x.superseded_by ? {superseded_by: clean(x.superseded_by)} : {}),
    excerpts: excerptsOf(x.answer),
  };
});
const line = (r) => clean([r.proposal_id, r.date_kind + " " + r.date, r.title, r.source_ref]
  .concat(r.superseded_by ? ["remplacée par " + r.superseded_by] : [])
  .concat([r.excerpts.join(" ")]).join(" | "));
const summary = results.map(line).join("\n") || "Aucune révision validée trouvée.";
return {results, summary, candidate_count: all.length, suppressed_count: all.length - results.length, excerpt_budget_chars: BUDGET};
